		/** 
		 * Tests creating a new ApiKey.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a ApiKey");

			StringBuilder msg = new StringBuilder( "-- Failed to create a ApiKey" );

			try {            
				ApiKey entity = ApiKeyService.getApiKeyInstance().createApiKey( generateNewEntity() );
				thePrimaryKey = entity.getApiKeyId();
				LOGGER.info( "-- Successfully created a ApiKey with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a ApiKey. 
		 */
		public ApiKey testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created ApiKey" );

			ApiKey entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read ApiKey with primary key" );
			msg.append( thePrimaryKey );
			
			ApiKeyFetchOneSummary fetchOneSummary = new ApiKeyFetchOneSummary( thePrimaryKey );

			try {
				entity = ApiKeyService.getApiKeyInstance().getApiKey( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found ApiKey " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a ApiKey.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a ApiKey." );

			StringBuilder msg = new StringBuilder( "Failed to update a ApiKey : " );        
			ApiKey entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created ApiKey." );

				// for use later on...
				thePrimaryKey = entity.getApiKeyId();

				ApiKeyService proxy = ApiKeyService.getApiKeyInstance();            
				proxy.updateApiKey( entity );   

				LOGGER.info( "-- Successfully saved ApiKey - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a ApiKey.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created ApiKey." );

			try{
			    ApiKey entity = testRead(); 
				ApiKeyService.getApiKeyInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted ApiKey with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete ApiKey with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all ApiKeys.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of ApiKeys:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all ApiKey : " );        
			List<ApiKey> collection  = null;

			try {
				// call the static get method on the ApiKeyService
				collection = ApiKeyService.getApiKeyInstance().getAllApiKey();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					ApiKey entity = null;            
					Iterator<ApiKey> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getApiKeyId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

