		protected ApiKey generateNewEntity() {
			ApiKey entity = new ApiKey( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),   new Date(),   new Date(),  null );
			
			return( entity );
		}

